export const categories = [
  { id: "produtividade", label: "Produtividade", icon: "zap" },
  { id: "desenvolvimento", label: "Desenvolvimento", icon: "code" },
  { id: "utilitarios", label: "Utilitários", icon: "wrench" },
  { id: "seguranca", label: "Segurança", icon: "shield" },
  { id: "design", label: "Design & Mídia", icon: "palette" },
  { id: "sistema", label: "Sistema", icon: "monitor" },
] as const;

export type Category = (typeof categories)[number]["id"];
export type Price = "free" | "freemium" | "paid" | "native";
export type Risk = "low" | "medium" | "high";
export type Chip = "silicon" | "intel";
export type Effort = "simple" | "medium" | "advanced";
export const priceLabels: Record<Price, string> = { free: "Gratuito", freemium: "Grátis com extras pagos", paid: "Pago", native: "Já vem no Mac" };
export const riskLabels: Record<Risk, string> = { low: "Baixo risco", medium: "Risco moderado", high: "Atenção extra" };
export const effortLabels: Record<Effort, string> = { simple: "Iniciante", medium: "Intermediário", advanced: "Avançado" };
export const categoryLabels = Object.fromEntries(categories.map(({ id, label }) => [id, label])) as Record<Category, string>;

export type Release = { version: string | null; published: string | null; url: string | null; source: string | null };
type Options = {
  repo?: string; brew?: string; formula?: string; changelog?: string; open?: boolean; chips?: Chip[]; minMac?: number;
  effort?: Effort; intents: string; keywords?: string; icon?: string; tone?: string; stars?: number; license?: string; permissions?: string;
};
export type Tool = {
  slug: string; name: string; category: Category; price: Price; risk: Risk; description: string;
  how: string; first: string; caution: string; website: string; release?: Release;
} & Options;

type Entry = [slug: string, name: string, category: Category, price: Price, risk: Risk, description: string, how: string, first: string, caution: string, website: string, options: Options];
const make = ([slug, name, category, price, risk, description, how, first, caution, website, options]: Entry): Tool => ({
  slug, name, category, price, risk, description, how, first, caution, website,
  chips: ["silicon", "intel"], effort: "simple", ...options,
});

