export const toolsBySlug = Object.fromEntries(tools.map((tool) => [tool.slug, tool])) as Record<string, Tool | undefined>;
export const brewPage = (tool: Tool) => tool.brew ? `https://formulae.brew.sh/cask/${tool.brew}` : tool.formula ? `https://formulae.brew.sh/formula/${tool.formula}` : null;
export const installCommand = (tool: Tool) => tool.brew ? `brew install --cask ${tool.brew}` : tool.formula ? `brew install ${tool.formula}` : null;
export function permissionsHint(tool: Tool): string {
  if (tool.permissions) return tool.permissions;
  if (tool.price === "native") return "Integrado ao sistema operacional (sem instalação externa)";
  const text = fold(`${tool.caution} ${tool.how} ${tool.first}`);
  const hints: string[] = [];
  if (text.includes("acessibilidade")) hints.push("Acessibilidade");
  if (text.includes("gravacao de tela") || text.includes("capturas")) hints.push("Gravação de Tela");
  if (text.includes("microfone")) hints.push("Microfone");
  if (text.includes("camera") || text.includes("webcam")) hints.push("Câmera");
  if (text.includes("calendario")) hints.push("Calendário");
  if (text.includes("acesso total ao disco")) hints.push("Acesso Total ao Disco");
  if (text.includes("teclado")) hints.push("Monitoramento de Entrada");
  if (text.includes("rede") || text.includes("firewall") || text.includes("vpn")) hints.push("Rede / Extensão de sistema");
  if (text.includes("finder")) hints.push("Automação do Finder");
  return hints.length ? hints.join(" · ") : tool.formula ? "Execução no Terminal (pastas do usuário)" : "Padrão de arquivos abertos por você";
}
export const fold = (value: string) => value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLocaleLowerCase("pt-BR");
const dateFormat = new Intl.DateTimeFormat("pt-BR", { day: "2-digit", month: "short", year: "numeric", timeZone: "UTC" });
export const shortDate = (date: string) => dateFormat.format(new Date(`${date}T00:00:00Z`)).replaceAll(" de ", " ").replaceAll(".", "");
export function findTools(list: Tool[], query: string) {
  const words = fold(query).trim().split(/\s+/).filter(Boolean);
  if (!words.length) return list;
  return list.map((tool, index) => {
    const name = fold(tool.name);
    const text = fold([tool.name, categoryLabels[tool.category], tool.description, tool.how, tool.keywords, priceLabels[tool.price], tool.slug].join(" "));
    if (!words.every((word) => text.includes(word))) return { tool, score: 0, index };
    return { tool, score: 1 + (name.includes(words.join(" ")) ? 20 : 0) + words.filter((word) => name.includes(word)).length, index };
  }).filter((result) => result.score > 0).sort((a, b) => b.score - a.score || a.index - b.index).map((result) => result.tool);
}
